/**
 * GÉNÉRATEUR DE LA PORTE DES GABARITS DE RÉGLAGES NATIFS.
 *
 * ⛔ UN GABARIT DE RÉGLAGES BP3 N'EST PAS UNE LIBRAIRIE — décision Romain, 2026-08-21
 * (`les-gabarits-de-reglages-natifs-sortent-des-librairies`). Rien ne l'invoque, il ne déclare
 * aucun mot, et il porte les réglages d'UNE pièce, pas un vocabulaire partagé.
 *
 * ⛔ CE QU'IL FAUSSAIT, ET C'EST LA RAISON DU GESTE : mesuré le 2026-08-21, il polluait TROIS de mes
 * comptes — 131 valeurs de `unit` en prose sur 133, 14 plages en texte sur 15, et 64 réglages
 * non transposables. Chaque règle sur les librairies devait l'excepter une par une. Après ce geste,
 * une règle qui porte sur les librairies porte sur TOUTES les librairies.
 *
 * ⚠️ ET LE SORTIR DE `lib/` FERMAIT SA SEULE PORTE : `lib/` n'est pas déclaré dans mes exports, donc
 * bp3-frontend ne lit pas le fichier — il lit la CLÉ `bp3-settings-template` dans le bundle. Le
 * déménagement n'est donc pas un rangement, c'est une fermeture de porte, et il lui en faut une
 * autre. Sa clé ne bouge pas : son témoin cherche une clé, pas un chemin.
 *
 * ⚠️ LES TROIS AUTRES GABARITS RESTENT — `settings/notreich`, `settings/test1`,
 * `settings/pattern_grammar` sont atteignables par le mot de leur parent (`settings.notreich`
 * compile, `settings.zorglub` refuse). Ils sont dans l'espace de la librairie `settings`, qui
 * déclare son mot et reste. Deux d'entre eux sont invoqués par des scènes réelles.
 *
 * Usage : node src/transpiler/gabarits-bundle.mjs > src/transpiler/gabarits-data.js
 */
import { readFileSync, readdirSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { dirname, join } from 'node:path';

const __dirname = dirname(fileURLToPath(import.meta.url));
const DOSSIER = 'gabarits';
const racine = join(__dirname, '..', '..', DOSSIER);

const gabarits = {};
for (const entree of readdirSync(racine).sort()) {
  if (!entree.endsWith('.json')) continue;
  // ⛔ LA CLÉ EST LE NOM DU FICHIER SANS SON EXTENSION — la MÊME qu'elle avait dans le bundle des
  // librairies. C'est ce qui rend la bascule d'une ligne chez bp3-frontend : il cherche une clé.
  gabarits[entree.replace(/\.json$/, '')] = JSON.parse(readFileSync(join(racine, entree), 'utf-8'));
}

// ⛔ ET LE GÉNÉRATEUR REFUSE DE PRODUIRE UNE PORTE VIDE, comme celle du schéma de syntaxe. Un
// dossier vidé publierait « aucun gabarit », qui a exactement la graphie d'une mesure — et le
// témoin de bp3-frontend compare DEUX ENSEMBLES : il verrait un paquet cohérent avec un dossier
// vide, donc vert, sur une donnée disparue.
if (!Object.keys(gabarits).length) {
  console.error(`[gabarits] ⛔ aucun gabarit trouvé dans ${DOSSIER}/ — la porte ne se publie pas `
    + `vide. Un consommateur lirait « ce dépôt n'a aucun gabarit », qui a la graphie d'une mesure.`);
  process.exit(1);
}

let sortie = '// Auto-generated by gabarits-bundle.mjs — do not edit\n';
sortie += '// LES GABARITS DE RÉGLAGES NATIFS BP3 — les réglages d\'une pièce, pas un vocabulaire.\n';
sortie += '// Artefact VERSIONNÉ, clés identiques à celles qu\'ils portaient dans le bundle des libs.\n\n';
sortie += `const GABARITS = ${JSON.stringify(gabarits)};\n\n`;
sortie += 'export { GABARITS };\n';
process.stdout.write(sortie);
